const payload = $input.item.json.body || {};
const lojaId = payload.loja_id ? parseInt(payload.loja_id, 10) : null;
const search = (payload.search || '').trim();
const origem = (payload.origem && payload.origem !== 'todos') ? payload.origem.trim() : '';
const limit = parseInt(payload.limit || '50', 10);
const offset = parseInt(payload.offset || '0', 10);

return {
  json: {
    lojaId,
    search,
    origem,
    limit,
    offset
  }
};

const items = $input.all();
const contatos = items.map(item => item.json).filter(c => c.id !== undefined);

return {
  json: {
    ok: true,
    contatos
  }
};
